{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C12", "C06", "C39", "C27", "C38", "C37", "C09", "C03", "C30", "C33"],
      "claim": "Nifedipine oral bioavailability is consistently reported as 35-68% in humans, well above the 20% threshold."
    },
    {
      "card_ids": ["C35", "C04", "C18", "C29", "C08", "C11", "C41", "C32", "C20", "C07"],
      "claim": "Isradipine systemic availability in healthy volunteers is mostly 16-19%, below 20%; one estimate is 28% and cirrhosis raises it to about 37%."
    },
    {
      "card_ids": ["C24", "C16", "C42"],
      "claim": "Additional direct human studies report oral bioavailability of 34%, 50%, and 90%, all above 20%."
    },
    {
      "card_ids": ["C02"],
      "claim": "Elagolix is described as having good oral bioavailability, qualitatively supporting F >= 20%."
    },
    {
      "card_ids": ["C26", "C13"],
      "claim": "Nabumetone active metabolite showed 38% absolute bioavailability in healthy subjects and 32% systemic availability in cirrhosis, supporting high."
    },
    {
      "card_ids": ["C40", "C22"],
      "claim": "TSU-68/ORH-2014 showed 42% absolute bioavailability after meals and is described as having high bioavailability."
    },
    {
      "card_ids": ["C34", "C10", "C43", "C23", "C05", "C25", "C31", "C28", "C14", "C36"],
      "claim": "Pentazocine oral bioavailability in healthy/normal subjects is 11-18.5%, below 20%; cirrhosis increases it to about 68-70%."
    },
    {
      "card_ids": ["C17", "C21", "C19", "C01", "C15"],
      "claim": "Rigosertib absolute bioavailability was 34.8-35% in fasting patients but 13.9% in fed patients; one qualitative report calls it low."
    }
  ],
  "confidence": "moderate",
  "contradictory_card_ids": ["C35", "C04", "C18", "C29", "C08", "C11", "C34", "C10", "C43", "C23", "C05", "C25", "C31", "C28", "C01", "C15"],
  "decision_summary": "The balance of transferred evidence, especially multiple direct human absolute/systemic bioavailability measurements, supports F >= 20%; low values are mostly limited to isradipine and pentazocine in healthy subjects and fed-state rigosertib.",
  "evidence_gaps": [
    "Query condition (fasted/fed, healthy/disease) is unspecified; some evidence is condition-dependent, with isradipine and pentazocine higher in cirrhosis and rigosertib lower when fed.",
    "Qualitative reports (C02, C15, C22) lack numeric F values, limiting quantitative weighting.",
    "Isradipine has one high estimate (C41) among predominantly low healthy-subject values, adding uncertainty."
  ],
  "new_evidence_assessment": [],
  "prediction_basis_card_ids": ["C12", "C06", "C39", "C27", "C38", "C37", "C09", "C03", "C30", "C33", "C41", "C32", "C20", "C07", "C24", "C02", "C26", "C13", "C22", "C40", "C19", "C17", "C21", "C16", "C42", "C14", "C36"],
  "revision_action": "initial",
  "supportive_card_ids": ["C12", "C06", "C39", "C27", "C38", "C37", "C09", "C03", "C30", "C33", "C41", "C32", "C20", "C07", "C24", "C02", "C26", "C13", "C22", "C40", "C19", "C17", "C21", "C16", "C42", "C14", "C36"]
}

